#!/usr/bin/env bash
#
# Installer for the `a` CLI:
#
#   curl -fsSL https://raw.githubusercontent.com/Sloy/a/main/install.sh | bash
#
# Clones (or updates) the repo into $A_HOME (default ~/.a) and adds one line to
# your shell rc that sources init.sh. Safe to run again.
#
#   A_HOME=<dir>        install somewhere other than ~/.a
#   A_REPO=<url>        clone from a different remote or a local path
#   A_NO_MODIFY_RC=1    skip the rc edit, e.g. when dotfiles source init.sh
#
# AI DISCLOSURE: This script was entirely generated by an AI tool
set -euo pipefail

A_REPO="${A_REPO:-https://github.com/Sloy/a.git}"
A_HOME="${A_HOME:-$HOME/.a}"

info() { printf '\033[36m==>\033[0m %s\n' "$*"; }
warn() { printf '\033[31m!\033[0m %s\n' "$*" >&2; }
fail() { warn "$*"; exit 1; }

command -v git >/dev/null 2>&1 || fail "git is required. Install it with: xcode-select --install"

if [[ -d "$A_HOME/.git" ]]; then
  info "Updating existing install in $A_HOME"
  git -C "$A_HOME" pull --ff-only --quiet || fail "could not update $A_HOME. Resolve it with git and rerun."
elif [[ -e "$A_HOME" ]]; then
  fail "$A_HOME already exists and is not an a install. Move it away or set A_HOME."
else
  info "Cloning $A_REPO into $A_HOME"
  git clone --quiet "$A_REPO" "$A_HOME" || fail "could not clone $A_REPO"
fi

source_line="[ -f \"$A_HOME/init.sh\" ] && . \"$A_HOME/init.sh\""

if [[ -n "${A_NO_MODIFY_RC:-}" ]]; then
  info "Skipping shell rc (A_NO_MODIFY_RC is set). Source init.sh yourself:"
  printf '    %s\n' "$source_line"
else
  case "$(basename "${SHELL:-zsh}")" in
    bash) rc="$HOME/.bashrc" ;;
    *)    rc="$HOME/.zshrc" ;;
  esac
  if [[ -f "$rc" ]] && grep -qF "$A_HOME/init.sh" "$rc"; then
    info "$rc already sources a"
  else
    printf '\n# a: android adb helpers (https://github.com/Sloy/a)\n%s\n' "$source_line" >> "$rc"
    info "Added a to $rc"
  fi
fi

command -v fzf >/dev/null 2>&1 || warn "fzf not found; interactive menus need it: brew install fzf"
command -v adb >/dev/null 2>&1 || warn "adb not found in PATH; add \$ANDROID_HOME/platform-tools to PATH"

info "Done. Open a new terminal (or run: . \"$A_HOME/init.sh\") and type: a"
